// Atmospheric Background Image Base64 Data URI for Offline & Cross-System Portability
window.EMBEDDED_BG_IMAGE = "data:image/jpeg;base64,";

(function() {
  function applyBg() {
    try {
      var watermark = document.querySelector('.ambient-bg-watermark');
      var hero = document.querySelector('.hero-background-image');
      if (!watermark && !hero) return;

      var applyFallback = function() {
        if (window.EMBEDDED_BG_IMAGE) {
          if (watermark) watermark.style.backgroundImage = 'url("' + window.EMBEDDED_BG_IMAGE + '")';
          if (hero) hero.style.backgroundImage = 'url("' + window.EMBEDDED_BG_IMAGE + '")';
        }
      };

      var testImg = new Image();
      testImg.onload = function() {
        // Loaded successfully from assets/
      };
      testImg.onerror = function() {
        var testImg2 = new Image();
        testImg2.onload = function() {
          if (watermark) watermark.style.backgroundImage = 'url("unimat_site_repair.jpg")';
          if (hero) hero.style.backgroundImage = 'url("unimat_site_repair.jpg")';
        };
        testImg2.onerror = function() {
          applyFallback();
        };
        testImg2.src = 'unimat_site_repair.jpg';
      };
      testImg.src = 'assets/unimat_site_repair.jpg';
    } catch(e) {}
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyBg);
  } else {
    applyBg();
  }
})();
